   59     * Returns null if not authenticated or still loading.
   60     */
   61    getCurrentUserSync(): User | null {
   62      return this.currentUserSubject.getValue();
   63    }
   64  
   65    private retryAttempt = 0;
   66    private retrySubscription: Subscription | null = null;
   67  
   68    constructor(
   69      private readonly http: HttpClient,
   70      private readonly jwtService: JwtService,
   71      private readonly router: Router,
   72    ) {}
   73  
   74    login(credentials: { email: string; password: string }): Observable<{ user: User }> {
