   89    getCurrentUser(): Observable<{ user: User }> {
   90      return this.http.get<{ user: User }>('/user').pipe(
   91        tap({
   92          next: ({ user }) => this.setAuth(user),
   93          error: (err: HttpErrorResponse) => this.handleAuthError(err),
   94        }),
   95        shareReplay(1),
   96        catchError(() => EMPTY),
   97      );
   98    }
